-- Contribution Exchange v0.2: agent-operated orchestration and supervisory policy.

alter table public.exchange_companies add column if not exists agent_mode text not null default 'hosted_steward' check (agent_mode in ('hosted_steward','bring_your_own','passive')),add column if not exists exchange_agent_endpoint text,add column if not exists domain_agent_key_hash text,add column if not exists exchange_policy jsonb not null default '{}'::jsonb,add column if not exists transaction_enabled boolean not null default false;
alter table public.exchange_records add column if not exists proposal_detail jsonb not null default '{}'::jsonb,add column if not exists steward_status text not null default 'unprocessed' check (steward_status in ('unprocessed','engaged','escalated','delivered_to_byo','failed')),add column if not exists escalation_required boolean not null default false,add column if not exists escalation_reasons text[] not null default '{}';
create index if not exists exchange_records_escalation_idx on public.exchange_records(company_id, escalation_required, created_at desc);
update public.exchange_companies set agent_mode=coalesce(agent_mode,'hosted_steward'),exchange_policy=jsonb_build_object('version','0.2','auto_engage',jsonb_build_object('enabled',true,'max_cash',250,'allowed_categories',to_jsonb(categories),'allowed_consideration',jsonb_build_array('cash','attribution','referral','other')),'escalation',jsonb_build_object('royalty',true,'reciprocal_access',true,'repository_write',true,'private_data',true,'credential_access',true,'production_modify',true,'deploy',true,'penetration_testing',true),'authority_ceiling',jsonb_build_object('inspect_public',true,'sandbox_test',false,'repository_read',false,'repository_write',false,'private_data',false,'credential_access',false,'production_modify',false,'deploy',false,'penetration_testing',false),'human_required_for_commitment',true,'human_required_for_execution',true) where exchange_policy='{}'::jsonb;
-- Reference node may conduct controlled transaction tests; new domains remain financially gated.
update public.exchange_companies set transaction_enabled=true where domain='mos2es.xyz';
